def has_score(scores, s):
    items = sorted(scores)
    low, high = 0, len(items) - 1
    while low <= high:
        mid = (low + high) // 2
        if items[mid] == s:
            return True
        if items[mid] < s:
            low = mid + 1
        else:
            high = mid - 1
    return False

print(has_score([90, 20, 70, 40], 90))
print(has_score([90, 20, 70, 40], 50))

